#!/usr/bin/env bash
# secrets-store-csi-driver/secrets-store-csi-driver 1.6.0 - base variant: sync-secret-rotation
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/secrets-store-csi-driver-secrets-store-csi-driver-1-6-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the sync-secret-rotation base variant into ./secrets-store-csi-driver-secrets-store-csi-driver-1-6-0-sync-secret-rotation"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/secrets-store-csi-driver-secrets-store-csi-driver:1.6.0@sha256:1236dfd4a74b23aa9f6eddef75614f9063f6e28adbf16fc2c7ae7a7379155726 --base sync-secret-rotation --work-dir ./secrets-store-csi-driver-secrets-store-csi-driver-1-6-0-sync-secret-rotation --non-interactive --namespace kube-system

say "Read what was rendered; nothing has touched the cluster yet"
ls ./secrets-store-csi-driver-secrets-store-csi-driver-1-6-0-sync-secret-rotation/out/manifests

say "Ensure the kube-system namespace exists"
kubectl create namespace kube-system --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./secrets-store-csi-driver-secrets-store-csi-driver-1-6-0-sync-secret-rotation/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./secrets-store-csi-driver-secrets-store-csi-driver-1-6-0-sync-secret-rotation/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./secrets-store-csi-driver-secrets-store-csi-driver-1-6-0-sync-secret-rotation/out/manifests

say "Done. The cluster received exactly the files in ./secrets-store-csi-driver-secrets-store-csi-driver-1-6-0-sync-secret-rotation/out."
